import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_batch_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor num_batches_tracked,
    bool training);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

namespace cute_batch_norm_detail {


constexpr int kThreads = 256;
constexpr float kMomentum = 0.1f;
constexpr float kEps = 1.0e-5f;

__global__ void cute_batch_norm_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ weight_ptr,
    const float* __restrict__ bias_ptr,
    float* __restrict__ running_mean_ptr,
    float* __restrict__ running_var_ptr,
    int64_t* __restrict__ num_batches_tracked_ptr,
    float* __restrict__ y_ptr,
    int N,
    int C,
    int H,
    int W,
    bool training)
{
    extern __shared__ float smem[];
    float* sum_smem = smem;
    float* sqsum_smem = smem + kThreads;

    int c = static_cast<int>(blockIdx.x);
    int tid = static_cast<int>(threadIdx.x);

    if (c >= C) {
        return;
    }

    int spatial = H * W;
    int elems_per_channel = N * spatial;

    auto x = cute::make_tensor(
        cute::make_gmem_ptr(x_ptr),
        cute::make_shape(N, C, H, W),
        cute::make_stride(C * H * W, H * W, W, 1));

    __shared__ float mean_shared;
    __shared__ float inv_std_shared;
    if (training) {
        float sum = 0.0f;
        float sqsum = 0.0f;
        for (int linear = tid; linear < elems_per_channel; linear += kThreads) {
            int n = linear / spatial;
            int rem = linear - n * spatial;
            int h = rem / W;
            int w = rem - h * W;
            float v = x(n, c, h, w);
            sum += v;
            sqsum += v * v;
        }
        sum_smem[tid] = sum;
        sqsum_smem[tid] = sqsum;
        __syncthreads();
        for (int stride = kThreads / 2; stride > 0; stride >>= 1) {
            if (tid < stride) {
                sum_smem[tid] += sum_smem[tid + stride];
                sqsum_smem[tid] += sqsum_smem[tid + stride];
            }
            __syncthreads();
        }
        if (tid == 0) {
            float count = static_cast<float>(elems_per_channel);
            float mean = sum_smem[0] / count;
            float variance = sqsum_smem[0] / count - mean * mean;
            variance = variance > 0.0f ? variance : 0.0f;
            mean_shared = mean;
            inv_std_shared = rsqrtf(variance + kEps);
            // BatchNorm uses biased variance for normalization and
            // unbiased variance for the running variance update.
            float unbiased_variance = variance;
            if (elems_per_channel > 1) {
                unbiased_variance =
                    variance * (count / static_cast<float>(elems_per_channel - 1));
            }
            running_mean_ptr[c] =
                (1.0f - kMomentum) * running_mean_ptr[c] + kMomentum * mean;
            running_var_ptr[c] =
                (1.0f - kMomentum) * running_var_ptr[c] +
                kMomentum * unbiased_variance;
            if (c == 0) {
                *num_batches_tracked_ptr += 1;
            }
        }
    } else {
        if (tid == 0) {
            mean_shared = running_mean_ptr[c];
            inv_std_shared = rsqrtf(running_var_ptr[c] + kEps);
        }
    }
    __syncthreads();

    float gamma = weight_ptr[c];
    float beta = bias_ptr[c];

    auto y = cute::make_tensor(
        cute::make_gmem_ptr(y_ptr),
        cute::make_shape(N, C, H, W),
        cute::make_stride(C * H * W, H * W, W, 1));

    for (int linear = tid; linear < elems_per_channel; linear += kThreads) {
        int n = linear / spatial;
        int rem = linear - n * spatial;
        int h = rem / W;
        int w = rem - h * W;

        float value = x(n, c, h, w);
        y(n, c, h, w) =
            (value - mean_shared) * inv_std_shared * gamma + beta;
    }
}

}  // namespace cute_batch_norm_detail


torch::Tensor cute_batch_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor num_batches_tracked,
    bool training)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(running_mean.is_cuda(), "running_mean must be a CUDA tensor");
    TORCH_CHECK(running_var.is_cuda(), "running_var must be a CUDA tensor");
    TORCH_CHECK(num_batches_tracked.is_cuda(),
                "num_batches_tracked must be a CUDA tensor");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");
    TORCH_CHECK(running_mean.scalar_type() == at::kFloat,
                "running_mean must be float32");
    TORCH_CHECK(running_var.scalar_type() == at::kFloat,
                "running_var must be float32");
    TORCH_CHECK(num_batches_tracked.scalar_type() == at::kLong,
                "num_batches_tracked must be int64");

    TORCH_CHECK(x.dim() == 4, "x must have shape (N, C, H, W)");
    TORCH_CHECK(weight.dim() == 1, "weight must be 1D");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");
    TORCH_CHECK(running_mean.dim() == 1, "running_mean must be 1D");
    TORCH_CHECK(running_var.dim() == 1, "running_var must be 1D");

    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
    TORCH_CHECK(running_mean.is_contiguous(),
                "running_mean must be contiguous");
    TORCH_CHECK(running_var.is_contiguous(),
                "running_var must be contiguous");
    TORCH_CHECK(num_batches_tracked.is_contiguous(),
                "num_batches_tracked must be contiguous");

    int N = static_cast<int>(x.size(0));
    int C = static_cast<int>(x.size(1));
    int H = static_cast<int>(x.size(2));
    int W = static_cast<int>(x.size(3));
    TORCH_CHECK(N > 0 && C > 0 && H > 0 && W > 0,
                "BatchNorm dimensions must be nonzero");

    TORCH_CHECK(weight.size(0) == C, "weight has incorrect size");
    TORCH_CHECK(bias.size(0) == C, "bias has incorrect size");
    TORCH_CHECK(running_mean.size(0) == C,
                "running_mean has incorrect size");
    TORCH_CHECK(running_var.size(0) == C,
                "running_var has incorrect size");

    auto y = torch::empty_like(x);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    dim3 grid(static_cast<unsigned int>(C), 1, 1);
    dim3 block(cute_batch_norm_detail::kThreads, 1, 1);
    size_t shared_bytes = 2 * cute_batch_norm_detail::kThreads * sizeof(float);

    cute_batch_norm_detail::cute_batch_norm_kernel<<<grid, block, shared_bytes, stream>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        num_batches_tracked.data_ptr<int64_t>(),
        y.data_ptr<float>(),
        N,
        C,
        H,
        W,
        training);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE batch normalization kernel launch failed");

    return y;
}
"""


cute_ext = load_inline(
    name="cute_batch_norm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_batch_norm"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_features: int) -> None:
        super().__init__()

        self.num_features = num_features
        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer(
            "num_batches_tracked",
            torch.tensor(0, dtype=torch.long),
        )

        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_batch_norm(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.num_batches_tracked,
            self.training,
        )

