        int w = rem - h * W;

        float value = x(n, c, h, w);
        y(n, c, h, w) =
            (value - mean_shared) * inv_std_shared * gamma + beta;
    }
}

}  // namespace cute_batch_norm_detail


torch::Tensor cute_batch_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor num_batches_tracked,
    bool training)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(running_mean.is_cuda(), "running_mean must be a CUDA tensor");
    TORCH_CHECK(running_var.is_cuda(), "running_var must be a CUDA tensor");
    TORCH_CHECK(num_batches_tracked.is_cuda(),
                "num_batches_tracked must be a CUDA tensor");

    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");
    TORCH_CHECK(running_mean.scalar_type() == at::kFloat,
                "running_mean must be float32");
    TORCH_CHECK(running_var.scalar_type() == at::kFloat,
                "running_var must be float32");
    TORCH_CHECK(num_batches_tracked.scalar_type() == at::kLong,
                "num_batches_tracked must be int64");

    TORCH_CHECK(x.dim() == 4, "x must have shape (N, C, H, W)");
    TORCH_CHECK(weight.dim() == 1, "weight must be 1D");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");
    TORCH_CHECK(running_mean.dim() == 1, "running_mean must be 1D");
    TORCH_CHECK(running_var.dim() == 1, "running_var must be 1D");

    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
    TORCH_CHECK(bias.is_contiguous(), "bias must be contiguous");
    TORCH_CHECK(running_mean.is_contiguous(),
                "running_mean must be contiguous");
    TORCH_CHECK(running_var.is_contiguous(),
                "running_var must be contiguous");
    TORCH_CHECK(num_batches_tracked.is_contiguous(),
                "num_batches_tracked must be contiguous");

    int N = static_cast<int>(x.size(0));
    int C = static_cast<int>(x.size(1));
    int H = static_cast<int>(x.size(2));
    int W = static_cast<int>(x.size(3));
    TORCH_CHECK(N > 0 && C > 0 && H > 0 && W > 0,
                "BatchNorm dimensions must be nonzero");

    TORCH_CHECK(weight.size(0) == C, "weight has incorrect size");
    TORCH_CHECK(bias.size(0) == C, "bias has incorrect size");
    TORCH_CHECK(running_mean.size(0) == C,
                "running_mean has incorrect size");
    TORCH_CHECK(running_var.size(0) == C,
                "running_var has incorrect size");

    auto y = torch::empty_like(x);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    dim3 grid(static_cast<unsigned int>(C), 1, 1);
    dim3 block(cute_batch_norm_detail::kThreads, 1, 1);
    size_t shared_bytes = 2 * cute_batch_norm_detail::kThreads * sizeof(float);

    cute_batch_norm_detail::cute_batch_norm_kernel<<<grid, block, shared_bytes, stream>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        num_batches_tracked.data_ptr<int64_t>(),
        y.data_ptr<float>(),
        N,
        C,
        H,
        W,
        training);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE batch normalization kernel launch failed");

    return y;
}
